let kml = msg.payload;
let coordinatesStr = "";

try {
    let document = kml.kml.Document[0];

    // Helper to find coordinates in any Placemark with a LineString
    function findLineString(obj) {
        if (!obj) return null;
        if (Array.isArray(obj)) {
            for (let item of obj) {
                let res = findLineString(item);
                if (res) return res;
            }
        }
        if (obj.Placemark) {
            let res = findLineString(obj.Placemark);
            if (res) return res;
        }
        if (obj.LineString && obj.LineString[0] && obj.LineString[0].coordinates) {
            return obj.LineString[0].coordinates[0];
        }
        if (obj.Folder) {
            let res = findLineString(obj.Folder);
            if (res) return res;
        }
        return null;
    }

    coordinatesStr = findLineString(document);

    if (!coordinatesStr) {
        throw new Error("No LineString found in KML");
    }
} catch (e) {
    node.error("Failed to parse KML: " + e.message);
    node.status({fill:"red",shape:"ring",text:"Parse Error: " + e.message});
    return null;
}

let coords = coordinatesStr.trim().split(/\s+/).map(c => {
    let parts = c.split(',');
    return {
        lon: parseFloat(parts[0]),
        lat: parseFloat(parts[1])
    };
}).filter(p => !isNaN(p.lat) && !isNaN(p.lon));

if (coords.length === 0) {
    node.error("No valid coordinates found in string");
    node.status({fill:"red",shape:"ring",text:"No valid points"});
    return null;
}

flow.set("coordinates", coords);
flow.set("index", 0);
node.status({fill:"green",shape:"dot",text:"Loaded " + coords.length + " points"});
return { payload: "KML Loaded: " + coords.length + " points" };

let coords = flow.get("coordinates");
let index = flow.get("index") || 0;
let busId = env.get("SIM_BUS_ID") || "BUS001";

if (!coords || coords.length === 0) {
    node.status({fill:"red",shape:"ring",text:"No coordinates loaded"});
    return null;
}

let point = coords[index];
let nextIndex = (index + 1) % coords.length;
flow.set("index", nextIndex);

let heading = 0;
if (index > 0) {
    let prev = coords[index - 1];
    heading = Math.atan2(point.lon - prev.lon, point.lat - prev.lat) * 180 / Math.PI;
    if (heading < 0) heading += 360;
}

msg.payload = {
    busId: busId,
    lat: point.lat,
    lon: point.lon,
    speed: Number((30 + Math.random() * 30).toFixed(2)),
    heading: Math.round(heading),
    timestamp: new Date().toISOString()
};

msg.topic = "transport/bus/" + busId + "/location";
node.status({fill:"blue",shape:"dot",text:"Bus " + busId + " point " + index + "/" + coords.length});
return msg;

let busId = env.get("SIM_BUS_ID") || "BUS001";
msg.payload = {
    busId: busId,
    timestamp: new Date().toISOString()
};
msg.topic = "transport/bus/" + busId + "/heartbeat";
return msg;
